@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	bd_list = () =>{
		bd_listurl = 	"http://tingshu.kuwo.cn/v2/api/product/rank/tabList";
		return JSON.parse(java.ajax(bd_listurl)).data; 
		}
		push("🔥榜单🔥", null, 1, 1);
bd_list().map($ =>{			
		push($.name, null, 1, 1);
		push($.shareTitle, null, 1, 1);
   	tabId = $.id;
		list = $.tags;
	   list.map(($,index)=>{	   	     	    
 	    title = $.name;		    
	url =  `http://tingshu.kuwo.cn/v2/api/product/rank/dataList?platform=1&notrace=0&kweexVersion=1.1.5&source=kwplayer_ar_9.1.8.1_tqq.apk&rn=10&id=${$.id}&pn={{page}}&tabId=${tabId}&bksource=kwbook_ar_9.1.8.1_tqq.apk`;			 

	if(list.length > 3&&list.length!=4){
		if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
				}
				else if(list.length == 4){ push(title, url, 1, 0.4);}
				else{ push(title, url, 1, 0.25);}
  });
 });



fl = (i) =>{
			fl_url =  `http://tingshu.kuwo.cn/v2/api/search/filter/classify?platform=1&notrace=0&kweexVersion=1.1.5&source=kwplayer_ar_9.1.8.1_tqq.apk&vip=0&categoryId=${i}&version=9.1.8.1&appUid=2649447402&bksource=kwbook_ar_9.1.8.1_tqq.apk`;
return  JSON.parse(java.ajax(fl_url)).data; 		
		}

fl_list = () =>{
		fl_listurl = 	"http://tingshu.kuwo.cn/v2/api/product/index/tab";
		return JSON.parse(java.ajax(fl_listurl)).data.weakList; 
		}	
push("🔥分类🔥", null, 1, 1);				
		fl_list().map($ =>{			
		push($.name, null, 1, 1);
   	categoryId = JSON.parse($.url).params.categoryId;
		list = fl(categoryId);
	   list.map(($,index)=>{	   	     	    
 	    title = $.name;	
	url =  `http://tingshu.kuwo.cn/v2/api/search/filter/albums?platform=1&notrace=0&kweexVersion=1.1.5&source=kwplayer_ar_9.1.8.1_tqq.apk&rn=10&categoryId=${categoryId}&classifyId=${$.id}&pn={{page}}&sortType=playCnt&bksource=kwbook_ar_9.1.8.1_tqq.apk`;			 

	if(list.length > 3&&list.length!=4){
		if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
				}
				else if(list.length == 4){ push(title, url, 1, 0.4);}
				else{ push(title, url, 1, 0.25);}
  });
 });

JSON.stringify(sort);

